-- Load the star schema from staging. dim_date is generated by Python (calendar logic) before this script.

INSERT INTO dim_product (product_id, product_name, category, unit_cost_cents, list_price_cents, launch_date)
SELECT product_id, product_name, category, unit_cost_cents, list_price_cents, launch_date
FROM stg_products;

-- Inner joins on unique keys (order_id is the primary key of stg_orders, product_id of dim_product),
-- so one line gives exactly one fact row; the pipeline also reconciles the row counts afterwards.
-- Net amount = gross x (1 - discount), rounded half-up to the cent with integer arithmetic.
INSERT INTO fact_sales (
    order_id, line_number, date_key, order_date, product_id, customer_id, customer_segment, region,
    sales_channel, order_status, is_completed, quantity, unit_price_cents, discount_rate_bp,
    gross_amount_cents, discount_amount_cents, net_amount_cents, cost_amount_cents, margin_amount_cents
)
SELECT
    c.order_id, c.line_number, c.date_key, c.order_date, c.product_id, c.customer_id, c.customer_segment,
    c.region, c.sales_channel, c.order_status, c.is_completed, c.quantity, c.unit_price_cents, c.discount_bp,
    c.gross,
    c.gross - c.net,
    c.net,
    c.cost,
    c.net - c.cost
FROM (
    SELECT
        l.order_id, l.line_number, d.date_key, o.order_date, l.product_id, o.customer_id, o.customer_segment,
        o.region, o.sales_channel, o.order_status,
        CASE WHEN o.order_status = 'completed' THEN 1 ELSE 0 END AS is_completed,
        l.quantity, l.unit_price_cents, l.discount_bp,
        CAST(l.quantity AS BIGINT) * l.unit_price_cents AS gross,
        (CAST(l.quantity AS BIGINT) * l.unit_price_cents * (10000 - l.discount_bp) + 5000) / 10000 AS net,
        CAST(l.quantity AS BIGINT) * p.unit_cost_cents AS cost
    FROM stg_order_lines l
    JOIN stg_orders o ON o.order_id = l.order_id
    JOIN dim_product p ON p.product_id = l.product_id
    JOIN dim_date d ON d.full_date = o.order_date
) c;
